class ValueStoreWalBootstrapFailureSafetyTest {

	@TempDir
	Path directory;

	@Test
	void synchronousBootstrapReportsUnreadableOriginalValue() throws Exception {
		Path values = createValuesWithUnreadableTail();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config())) {
			assertThatThrownBy(() -> {
				try (ValueStore ignored = openStore(values, wal)) {
				}
			}).isInstanceOf(IOException.class);
		}
	}

	@Test
	void asynchronousBootstrapReportsFailureOnClose() throws Exception {
		Path values = createValuesWithUnreadableTail();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config(false))) {
			ValueStore store = openStore(values, wal);
			assertThatThrownBy(store::close).isInstanceOf(IOException.class);
		}
	}

	@Test
	void asynchronousBootstrapReportsFailureBeforeSyncSucceeds() throws Exception {
		Path values = createValuesWithUnreadableTail();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config(false))) {
			ValueStore store = openStore(values, wal);
			try {
				assertThatThrownBy(store::sync).isInstanceOf(IOException.class);
			} finally {
				try {
					store.close();
				} catch (IOException expected) {
					// Closing must release the native files even when it reports the same bootstrap failure.
				}
			}
		}
	}

	@Test
	void retryDoesNotRewriteAnUnchangedBootstrapTarget() throws Exception {
		Path values = createValuesWithUnreadableTail();
		attemptFailedBootstrap(values);
		Path marker = config().walDirectory().resolve(ValueStoreWAL.BOOTSTRAP_PENDING_FILE_NAME);
		assertThat(marker).exists();

		// A previous bootstrap may have durably written this target. Retrying must not open it with TRUNCATE_EXISTING.
		Files.setLastModifiedTime(marker, FileTime.fromMillis(946684800000L));
		FileTime beforeRetry = Files.getLastModifiedTime(marker);
		attemptFailedBootstrap(values);

		assertThat(marker).exists();
		assertThat(Files.getLastModifiedTime(marker)).isEqualTo(beforeRetry);
	}

	@Test
	void retryGrowsBootstrapTargetBeforeAppendingNewHistory() throws Exception {
		Path values = createValuesWithUnreadableTail();
		attemptFailedBootstrap(values);
		Path marker = config().walDirectory().resolve(ValueStoreWAL.BOOTSTRAP_PENDING_FILE_NAME);
		assertThat(readBootstrapTarget(marker)).isEqualTo(2);

		setTailLength(values, 1 + "tail".length());
		try (ValueStore store = new ValueStore(values.toFile())) {
			assertThat(store.storeValue(SimpleValueFactory.getInstance().createBNode("new"))).isEqualTo(3);
			store.sync();
		}
		setValueLength(values, 3, -1);
		attemptFailedBootstrap(values);
		assertThat(readBootstrapTarget(marker)).isEqualTo(3);

		setValueLength(values, 3, 1 + "new".length());
		try (ValueStoreWAL wal = ValueStoreWAL.open(config());
				ValueStore store = openStore(values, wal)) {
			assertThat(store.getValue(3).stringValue()).isEqualTo("new");
		}
		assertThat(marker).doesNotExist();
	}

	@Test
	void failedBootstrapCannotRecoverItsContiguousPrefixAsACompleteDictionary() throws Exception {
		Path values = createValuesWithUnreadableTail();
		attemptFailedBootstrap(values);
		deleteValueFiles(values);
		try (ValueStoreWAL wal = ValueStoreWAL.open(config())) {
			assertThatThrownBy(() -> {
				try (ValueStore ignored = openStore(values, wal)) {
				}
			}).isInstanceOf(IOException.class);
		}
	}

	@Test
	void repairedOriginalValuesCanFinishBootstrapAndLaterRecoverEveryId() throws Exception {
		Path values = createValuesWithUnreadableTail();
		attemptFailedBootstrap(values);
		setTailLength(values, 1 + "tail".length());
		try (ValueStoreWAL wal = ValueStoreWAL.open(config());
				ValueStore store = openStore(values, wal)) {
			assertThat(store.getValue(2).stringValue()).isEqualTo("tail");
		}
		deleteValueFiles(values);
		try (ValueStoreWAL wal = ValueStoreWAL.open(config());
				ValueStore recovered = openStore(values, wal)) {
			assertThat(recovered.getValue(1).stringValue()).isEqualTo("covered");
			assertThat(recovered.getValue(2).stringValue()).isEqualTo("tail");
		}
	}

	@Test
	void pendingBootstrapPreservesMarkerWhenHistoricalWalTailIsUnreadable() throws Exception {
		Path values = createValuesWithUnreadableTail();
		attemptFailedBootstrap(values);
		setTailLength(values, 1 + "tail".length());
		Path marker = config().walDirectory().resolve(ValueStoreWAL.BOOTSTRAP_PENDING_FILE_NAME);
		assertThat(marker).exists();
		Path segment;
		try (var files = Files.list(config().walDirectory())) {
			segment = files.filter(path -> path.getFileName().toString().endsWith(".v1"))
					.findFirst()
					.orElseThrow();
		}
		// A crash while writing the next frame can leave a valid dictionary prefix followed by a partial length.
		Files.write(segment, new byte[] { 1, 2 }, StandardOpenOption.APPEND);
		byte[] historicalBytes = Files.readAllBytes(segment);
		try (ValueStoreWAL wal = ValueStoreWAL.open(config())) {
			assertThat(wal.initialSummary().complete()).isFalse();
			assertThatThrownBy(() -> {
				try (ValueStore ignored = openStore(values, wal)) {
				}
			}).isInstanceOf(IOException.class);
		}
		assertThat(marker).exists();
		assertThat(Files.readAllBytes(segment)).containsExactly(historicalBytes);
	}

	private Path createValuesWithUnreadableTail() throws Exception {
		Path values = Files.createDirectory(directory.resolve("values"));
		try (ValueStore store = new ValueStore(values.toFile())) {
			assertThat(store.storeValue(SimpleValueFactory.getInstance().createBNode("covered"))).isEqualTo(1);
			assertThat(store.storeValue(SimpleValueFactory.getInstance().createBNode("tail"))).isEqualTo(2);
			store.sync();
		}
		setTailLength(values, -1);
		return values;
	}

	private void attemptFailedBootstrap(Path values) throws Exception {
		try (ValueStoreWAL wal = ValueStoreWAL.open(config())) {
			try (ValueStore ignored = openStore(values, wal)) {
				// Continue to the restart assertion even when the broken implementation swallowed this failure.
			} catch (IOException expected) {
				// A failed bootstrap must preserve a persistent indication that its WAL prefix is incomplete.
			}
		}
	}

	private ValueStoreWalConfig config() {
		return config(true);
	}

	private ValueStoreWalConfig config(boolean synchronous) {
		return ValueStoreWalConfig.builder()
				.walDirectory(directory.resolve("wal"))
				.storeUuid("bootstrap-failure-safety")
				.syncBootstrapOnOpen(synchronous)
				.recoverValueStoreOnOpen(true)
				.build();
	}

	private static ValueStore openStore(Path values, ValueStoreWAL wal) throws IOException {
		return new ValueStore(values.toFile(), false, 16, 16, 16, 16, wal);
	}

	private static void setTailLength(Path values, int length) throws IOException {
		setValueLength(values, 2, length);
	}

	private static void setValueLength(Path values, int id, int length) throws IOException {
		try (RandomAccessFile ids = new RandomAccessFile(values.resolve("values.id").toFile(), "r");
				RandomAccessFile data = new RandomAccessFile(values.resolve("values.dat").toFile(), "rw")) {
			ids.seek((long) id * Long.BYTES);
			data.seek(ids.readLong());
			data.writeInt(length);
		}
	}

	private static int readBootstrapTarget(Path marker) throws IOException {
		try (DataInputStream input = new DataInputStream(Files.newInputStream(marker))) {
			int target = input.readInt();
			assertThat(input.read()).isEqualTo(-1);
			return target;
		}
	}

	private static void deleteValueFiles(Path values) throws IOException {
		Files.delete(values.resolve("values.dat"));
		Files.delete(values.resolve("values.id"));
		Files.delete(values.resolve("values.hash"));
	}
}
